(5728,0,0,'我对上层精灵了解很少，对辛德拉更是一无所知。',9382,1,1,5727,0,0,0,'',0,0),
(5729,0,0,'这儿发生了什么？先知！',9380,1,1,5728,0,0,0,'',0,0),
(5733,0,0,'是啊，你真聪明。你觉得自己有多聪明呢，斯里基克？',9398,1,1,5733,0,0,0,'',0,0),
(5734,0,0,'那么，现在我是国王了……你们要供奉我什么？！',9451,1,1,5734,0,0,0,'',0,0),
(5735,0,0,'喊我“老大”。你们要供奉给我什么？！',9401,1,1,5735,0,0,0,'',0,0),
(5738,0,0,'额……我就是这样找到他们的。我要告诉国王他们是个威胁！船长说……我曾经听说卫兵芬古斯曾叫你大胖子，无用的矮子情人！',9423,1,1,0,0,0,0,'',0,0),
(5739,0,0,'嗯，我要在国王惩罚我以前带一些在外面发现的囚犯。',9421,1,1,5738,0,0,0,'',0,0),
(5740,0,0,'好吧……给我看看贡品！',9367,1,1,0,0,0,0,NULL,0,0),
(5743,0,0,'为巨大的损失表示哀悼。',9449,1,1,0,0,0,0,NULL,0,0),
(5743,1,0,'为巨大的损失表示哀悼。',9449,1,1,0,0,0,0,NULL,0,0),
(5749,0,0,'<将原理图抄写到工程笔记本中。>',9485,1,3,0,0,0,0,NULL,0,0),
(5750,0,0,'将我传送到熔火之心，洛索斯。',13491,1,1,0,0,0,0,'',0,0),
(5762,0,0,'雷克斯洛特，我把瑟银镣铐弄丢了。',9529,1,1,0,0,0,0,'',0,0),
(5764,0,0,'拉比恩，你为什么说这是个巧合？',9536,1,1,5765,0,0,0,'',0,0),
(5765,0,0,'丰饶之果？',9538,1,1,5766,0,0,0,'',0,0),
(5766,0,0,'但是，有些事情好像出了差错，是吗？',9540,1,1,5767,0,0,0,'',0,0),
(5767,0,0,'如果丰饶之果——或者说是魔藤——完全堕落，那会发生什么事呢？',9542,1,1,5768,0,0,0,'',0,0),
(5768,0,0,'下次再遇到这种事情的时候我会好好考虑一下的。',6089,1,1,0,0,0,0,'',0,0),
(5779,0,0,'要做什么？',0,1,1,5780,0,0,0,'',0,0),
(5780,0,0,'火焰领主和胆敢阻拦的人都会被我的愤怒所摧残。',0,1,1,5781,0,0,0,'',0,0),
(5781,0,0,'我要为辟地打扫出来一片地方。那是什么？',0,1,1,5783,0,0,0,'',0,0),
(5783,0,0,'给我一艘船，大领主。',0,1,1,0,0,0,0,'',0,0),
(5812,0,0,'你是能制造出源质的塑地者吗？',9576,1,1,5813,0,0,0,'',0,0),
(5813,0,0,'弗兰扎尔，你对此了解多少？',9578,1,1,5814,0,0,0,'',0,0),
(5814,0,0,'裂缝？',9580,1,1,5815,0,0,0,'',0,0),
(5815,0,0,'发生了什么事？',9582,1,1,5816,0,0,0,'',0,0),
