(5851,0,0,'血蹄酋长，也许这请求听起来有些奇怪……但是我正在照顾一个非常害羞的孩子。对他来说，你就是个英雄，是他请求我来拿到你的蹄印。',9670,1,1,5852,0,0,0,NULL,0,0),
