(5870,0,0,'这么说你是疯狂的克林弗兰？真不幸，我所期望的是一次真正的挑战。你敢以真面目视人吗？',9754,1,1,0,0,0,0,NULL,0,0),
(5871,0,0,'我知道你是摧毁者阿托留斯。恶魔，现身吧！',9751,1,1,0,0,0,0,NULL,0,0),
(5872,0,0,'侏儒？真可怜。面对我吧，恶魔！',9753,1,1,0,0,0,0,NULL,0,0),
