(6162,0,2,'我需要坐骑。',3409,4,8192,0,0,0,0,'',0,0),
(6182,0,0,'为什么你的东西都这么实惠？你还有利润吗？',10035,1,1,6181,0,0,0,NULL,0,0),
(6185,0,0,'正如我的君主所期望的那样，我当场就杀了那个人，因为他不过是一个小偷和骗子！',10049,1,1,6187,0,0,0,'',0,0),
(6185,1,0,'我把那人交给了我的君主惩处，因为他违反了这儿的法律，我有责任惩处他。',10050,1,1,6187,0,0,0,'',0,0),
(6185,2,0,'我没收了他偷来的玉米，警告他“偷窃是走向末日和毁灭的必经之路”，但是我让他回家了。',10051,1,1,6187,0,0,0,'',0,0),
(6185,3,0,'我允许他带了些足够他养几日家的玉米，鼓励了他几句，就让他离开了。',10052,1,1,6187,0,0,0,'',0,0),
(6186,0,0,'我已经准备好去寻找我的命运了！',10047,1,1,6185,0,0,0,'',0,0),
(6187,0,0,'我按照君主的指示处死了他，并且让他在临死前饱受折磨地死去，作为他对我的人民所犯罪行的惩处。',10075,1,1,6208,0,0,0,'',0,0),
(6187,1,0,'我按照王上的命令处决他，但是我尽可能地让他少受痛苦。正义必须得到伸张，但我们也要心怀怜悯。',10076,1,1,6208,0,0,0,'',0,0),
(6187,2,0,'我愿意以自己生命的代价来拯救他，然后他就可以证明自己的清白。如果可以的话，我会不惜一切代价来帮助他。',10077,1,1,6208,0,0,0,'',0,0),
