(6207,7,0,'告诉我更多关于风暴套卡的事情。',20892,1,1,8637,0,0,0,NULL,0,0),
(6207,8,0,'还有其他的套卡存在吗？',38603,1,1,11073,0,0,0,NULL,0,0),
(6208,0,0,'我挑战他的邪恶与蛮横，不惜一切代价捍卫王上的荣耀。',10079,1,1,6209,0,0,0,'',0,0),
(6208,1,0,'我平静但略有表示地对这种冒犯一言不发，让他对自己犯下的错心怀恐惧。回去之后，我会把这一切禀报王上。',10080,1,1,6209,0,0,0,'',0,0),
(6208,2,0,'我默不作声，忽略了这种侮辱。我不会告诉我的王上，因为我将不惜一切代价保护和平。这只是一次侮辱——而不是一次完全的宣战。',10081,1,1,6209,0,0,0,'',0,0),
(6209,0,0,'我会反对我的兄弟加入军队，即使我们的关系会因此产生永久的裂痕。对他自己和周围的人来说，他无疑是个危险，要想指望他会逐渐进步可就太冒险了。',10083,1,1,6210,0,0,0,'',0,0),
(6209,1,0,'我会支持我的兄弟加入军队，虽然这或许会威胁到军队的安全。我和军队的其他成员会帮助他，我相信他能够适应这儿的生活并且学会生存之道。',10084,1,1,6210,0,0,0,'',0,0),
(6209,2,0,'我会想办法让他不参加危险的任务，完全不需要他做任何事情，以此来保存我的家族的血脉。',10085,1,1,6210,0,0,0,'',0,0),
(6210,0,0,'我会把野兽的耳朵给我的长官看，并把击杀野兽归功于我，我自己花赏金。把别人的所作所为当做自己的行为是无耻的。',10087,1,1,6211,0,0,0,'',0,0),
(6210,1,0,'我会把野兽的耳朵给我的长官看，并声称是我自己杀死了野兽——毕竟，确实是我杀了它。然后我会把赏金给那些穷困潦倒的骑士补贴家用。',10088,1,1,6211,0,0,0,'',0,0),
(6210,2,0,'我将对这次击杀缄口不言，并且那些骑士必须向我保证要补贴家用。',10089,1,1,6211,0,0,0,'',0,0),
(6211,0,0,'我很乐意去追寻那些你提及的已定命运！我已经准备好了！',10091,1,1,0,0,0,0,'',0,0),
