(7531,0,0,'我是一名囚犯，它看起来像什么？在我离开太阳之门后，德莱尼就抓住了我。他们杀死了传送门控制者，摧毁了大门。太阳王对发生的这一切非常不满。',14626,1,1,7537,0,0,0,'',0,0),
