(9301,0,0,'快来，巴德。是时候和冰霜巨魔玩玩了！',25656,1,1,0,0,0,0,'',0,0),
(9302,0,0,'别再担心了，牦牛人。部落会拯救并保护你和你的人民，但是首先你必须拿到《部落的血誓》来宣誓向酋长效忠。',25649,1,1,9305,0,0,0,'',0,0),
(9303,0,0,'为了部落！\r\n\r\n从我们四周的箱子里取用武器，然后向东到阿格玛之锤报到。作为部落的一员，你的第一项试炼就是活着走完这段路。\r\n\r\nLok\'tar ogar！',25655,1,1,0,0,0,0,'',0,0),
(9304,0,0,'那就跟我重复：「Lok\'tar ogar！胜利或死亡——正是这句话把我与部落联结在一起。对任何部落战士而言，这都是最神圣、最根本的真理。\r\n\r\n我自愿把我的血肉献给大酋长。我是大酋长意志的器具。我是大酋长号令的武器。\r\n\r\n从此刻直到世界终结，我生也如此，死也如此——为了部落！」',25653,1,1,9303,0,0,0,'',0,0),
(9305,0,0,'是的，坦卡。惩罚是指定给部落成员的权利。',25651,1,1,9304,0,0,0,'',0,0),
(9307,0,0,'我还有点其他的事要问你。',24226,1,1,9046,0,0,0,'',0,0),
(9335,0,0,'嗯……青蛙说你就是叛徒，我的“朋友”。',25738,1,1,0,0,0,0,NULL,0,0),
