(21277,0,0,'好的。哪里？',11036,1,1,21278,0,0,0,NULL,0,0),
(21278,0,0,'铜须的……胡须啊！你在说什么！',11038,1,1,21279,0,0,0,NULL,0,0),
(21279,0,0,'鱼？你给了个什么？你说拯救艾泽拉斯所有生命的关键是一条鱼？',11040,1,1,21280,0,0,0,NULL,0,0),
(21280,0,0,'一条小鱼？大海里全都是小鱼！有一百万的好几次方条小鱼！',11042,1,1,21281,0,0,0,NULL,0,0),
(21281,0,0,'请继续吧。',69357,1,1,21282,0,0,0,NULL,0,0),
(21282,0,0,'你把一块鱼放在这里和东部王国之间的海域？这块鱼有这种特殊能力？',11046,1,1,21283,0,0,0,NULL,0,0),
(21283,0,0,'你疯了。',11048,1,1,21284,0,0,0,NULL,0,0),
(21284,0,0,'我在认真地听呢。',11050,1,1,21285,0,0,0,NULL,0,0),
(21285,0,0,'请再说一次。',11052,1,1,21286,0,0,0,NULL,0,0),
(21286,0,0,'好吧，我们直说吧。你把权杖放在了你在用阿纳克洛斯飞行时你自己创造的小鱼身上，现在你希望我制造一个……奥金鱼漂或者其它什么……用来抓住你那躲起来的小鱼？并且这可能招致一个元素领主的愤怒？我说错什么细节吗？也许我需要在一次日食，在闰年，并且不穿衣服的情况下去做这件事情？',11054,1,1,21287,0,0,0,NULL,0,0),
(21287,0,0,'太棒了！还有，敢问，我如何获得一个奥金鱼漂？',11057,1,1,21288,0,0,0,NULL,0,0),
(21288,0,0,'但是…',77157,1,1,0,0,0,0,NULL,0,0),
(21289,0,0,'我相信你。',36640,1,1,0,0,0,0,NULL,0,0),
(21290,0,0,'我需要答案，食人魔！',15283,1,1,21291,0,0,0,NULL,0,0),
(21291,1,0,'为什么巨石之拳离这这么远？你知道那是怪物的领土。',15285,1,1,21292,0,0,0,NULL,0,0),
(21292,2,0,'你认为你想吃什么就吃什么吗？很显然你正在尝试吃破碎的东西。',15287,1,1,21293,0,0,0,NULL,0,0),
(21293,3,0,'北部，希尔盖？',15289,1,1,21294,0,0,0,NULL,0,0),
(21295,0,0,'我已经杀了很多你说的食人魔，兰特瑞索。我并不害怕。',15315,1,1,21296,0,0,0,NULL,0,0),
(21310,0,0,'我想占用你一点时间，先生。',11731,1,1,21311,0,0,0,NULL,0,0),
(21311,0,0,'为什么呢，当然。我有一些事情需要在阁楼中向您汇报，安维尔德先生！',11733,1,1,0,0,0,0,NULL,0,0),
(21312,0,0,'你好，伊崔格。我从黑石塔带来了些消息。',5990,1,1,21313,0,0,0,'',0,0),
(21313,0,0,'只有一个大酋长，伊崔格！',5992,1,1,21314,0,0,0,'',0,0),
(21314,0,0,'你是什么意思？',46314,1,1,21315,0,0,0,'',0,0),
(21315,0,0,'壁炉谷？但是……',5996,1,1,21316,0,0,0,'',0,0),
(21316,0,0,'我会接受这个任务，伊崔格。',5998,1,1,21317,0,0,0,'',0,0),
(21317,0,0,'啊，这就是他们怎么把黑铁感到塔底的。',6000,1,1,21318,0,0,0,'',0,0),
(21318,0,0,'没准这里有条路？',6002,1,1,21319,0,0,0,'',0,0),
(21319,0,0,'随你的便吧，伊崔格。',6004,1,1,0,0,0,0,'',0,0),
(21321,0,0,'魂能是什么?',5756,1,1,2704,0,0,0,'',0,0),
(21322,0,0,'抱歉，我没想到你能听懂我说的话。你在这里做什么？',6243,1,1,21323,0,0,0,'',0,0),
(21323,0,0,'是吗？也许你该告诉我是什么让你烦恼的。',6245,1,1,21324,0,0,0,'',0,0),
(21324,0,0,'什么约定？',6247,1,1,21325,0,0,0,'',0,0),
(21325,0,0,'他是怎么破坏约定的？',6249,1,1,21326,0,0,0,'',0,0),
(21326,0,0,'也许我能提供一些帮助。我们来做个交易吧，萨特。我会杀了那头巨兽并带回未铸造的胸甲。作为交换，你要教我如何制造这个胸甲。',6251,1,1,0,0,0,0,'',0,0),
(21330,0,0,'我可没有犯错。',9902,1,1,21331,0,0,0,'',0,0),
(21331,0,0,'你像是迷失了自己，奈法利安。我听不懂你在说什么。',9904,1,1,21332,0,0,0,'',0,0),
(21332,0,0,'那就试试看吧。',9906,1,1,0,0,0,0,'',0,0),
(21333,0,0,'我无法战胜瓦拉斯塔兹，不过我可以辅助治疗你们。',9847,1,1,21334,0,0,0,'',0,0),
(21334,0,0,'瓦拉斯塔兹，不！！',10011,1,1,21332,0,0,0,'',0,0),
(21335,0,0,'我们已经准备好与你并肩作战了，阿卡玛。',21522,1,1,0,0,0,0,'',0,0),
(21400,0,0,'我需要一个塞纳里奥的灯笼。',5243,1,1,0,0,0,0,'',0,0),
(21400,1,0,'那是什么植物？对费伍德森林有那么大的污染？',5384,1,1,21401,0,0,0,'',0,0),
(21402,0,0,'我下定决心了。让我遗忘炼金专精吧！',21873,1,1,0,0,0,1500000,'遗忘知识是一笔昂贵的开销。你愿意付出代价吗？',21569,0),
(21403,0,0,'我下定决心了。让我遗忘炼金专精吧！',21873,1,1,0,0,0,1500000,'遗忘知识是一笔昂贵的开销。你愿意付出代价吗？',21569,0),
