(30201,1,0,'你能切换罗克迪洛尔吗？',10785,1,1,0,0,0,0,'',0,0),
(30211,0,2,'让我看看我能飞到哪里。',0,4,8192,0,0,0,0,'',0,0),
(30211,1,0,'我要飞往暮冬要塞。',0,1,1,0,0,0,0,'',0,0),
(30212,0,0,'眼睛指引我来到这儿，艾瑞斯。',0,1,1,30213,0,0,0,'',0,0),
(30213,0,0,'我很适合看这个？',0,1,1,30214,0,0,0,'',0,0),
(30214,0,0,'我不知道该怎么想，艾瑞斯。如果有什么需要帮助的话我会用我的力量帮助你。',0,1,1,30215,0,0,0,'',0,0),
(30215,0,0,'这么多天过去了，艾瑞斯。',0,1,1,30216,0,0,0,'',0,0),
(30216,0,0,'所以我怎么帮你？',0,1,1,30217,0,0,0,'',0,0),
(30228,0,0,'我弄丢了瓦塔拉克饰品的左半边。',0,1,1,0,0,0,0,'',0,0),
