(55002,1,0,'我愿意为温妮小姐拔出我的佩剑。',5936,1,131,0,0,0,0,NULL,0,0),
(56000,0,0,'恐惧魔王？你是说魔王贝恩霍勒。他向你问好，并有消息给你……',9737,1,1,56001,0,0,0,NULL,0,0),
(56001,0,0,'不，乌拉泰克。他知道你的秘密。他知道你跟克索诺斯的赫尔努拉斯之间的阴谋。',9739,1,1,56002,0,0,0,NULL,0,0),
(56002,0,0,'叛徒，我可没骗你。魔王贝恩霍勒想要你的命。',9741,1,1,0,0,0,0,NULL,0,0),
